CREATE OR REPLACE FUNCTION public.crm_automation_evaluate_pending()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 r record;
 v_blockers text[];
 v_state text;
 v_processed int:=0;
 v_scheduled int:=0;
 v_blocked int:=0;
 v_finished int:=0;
 v_review int:=0;
 v_purchase boolean;
 v_verified boolean;
 v_sender boolean;
BEGIN
 IF session_user <> 'postgres' AND auth.role() IS DISTINCT FROM 'service_role' THEN
   RAISE EXCEPTION 'crm_provider_only' USING ERRCODE='42501';
 END IF;
 SELECT automatic_sends_enabled INTO v_sender
 FROM public.crm_automation_settings WHERE singleton=true;
 -- Exact automation lifecycle is serialized; concurrent cron/webhook changes
 -- are read-only here, never turned into an actual send authorization.
 IF NOT pg_try_advisory_xact_lock(72180310,20261027) THEN
   RETURN jsonb_build_object('skipped','scan_already_running');
 END IF;
 FOR r IN
   SELECT f.id follow_up_id,f.conversation_id,f.status follow_up_status,
     f.due_at,f.created_at,c.status conversation_status,c.last_inbound_at,
     c.last_outbound_at,c.created_at conversation_created,
     u.phone_e164,u.consent_status,u.consent_at,u.consent_evidence,
     u.commercial_opt_out
   FROM public.crm_follow_ups f
   JOIN public.crm_conversations c ON c.id=f.conversation_id
   JOIN public.crm_customers u ON u.id=c.customer_id
   WHERE f.created_at > now()-interval '30 days'
   ORDER BY f.created_at DESC LIMIT 500
 LOOP
   v_processed:=v_processed+1;
   v_blockers:=ARRAY[]::text[];
   IF r.follow_up_status<>'pending' THEN
     v_state:='finished';
     v_finished:=v_finished+1;
   ELSIF r.due_at>now() THEN
     v_state:='scheduled';
     v_scheduled:=v_scheduled+1;
   ELSE
     v_state:='blocked';
     IF r.conversation_status<>'waiting_customer' THEN
       v_blockers:=array_append(v_blockers,'conversation_not_waiting');
     END IF;
     IF r.commercial_opt_out THEN
       v_blockers:=array_append(v_blockers,'customer_opted_out');
     END IF;
     IF r.consent_status<>'granted' OR r.consent_at IS NULL
        OR nullif(btrim(coalesce(r.consent_evidence,'')),'') IS NULL THEN
       v_blockers:=array_append(v_blockers,'consent_unverified');
     END IF;
     IF r.last_inbound_at IS NULL
       OR r.last_inbound_at<=now()-interval '23 hours'
       OR r.last_inbound_at>now()+interval '1 minute' THEN
       v_blockers:=array_append(v_blockers,'outside_verified_window');
     END IF;
     IF r.last_outbound_at IS NULL OR r.last_inbound_at IS NULL
       OR r.last_outbound_at<=r.last_inbound_at THEN
       v_blockers:=array_append(v_blockers,'business_reply_unverified');
     END IF;
     SELECT EXISTS(
       SELECT 1 FROM public.crm_tintim_message_events e
       WHERE e.conversation_id=r.conversation_id AND e.direction='inbound'
         AND e.time_basis='provider_timestamp'
         AND e.occurred_at BETWEEN now()-interval '23 hours' AND now()
         AND r.last_inbound_at IS NOT NULL
         AND e.occurred_at BETWEEN r.last_inbound_at-interval '2 minutes'
                               AND r.last_inbound_at+interval '2 minutes'
     ) OR EXISTS (
       SELECT 1 FROM public.crm_whatsapp_message_events e
       WHERE e.conversation_id=r.conversation_id AND e.direction='inbound'
         AND e.occurred_at BETWEEN now()-interval '23 hours' AND now()
         AND r.last_inbound_at IS NOT NULL
         AND e.occurred_at BETWEEN r.last_inbound_at-interval '2 minutes'
                               AND r.last_inbound_at+interval '2 minutes'
     ) INTO v_verified;
     IF NOT v_verified THEN
       v_blockers:=array_append(v_blockers,'provider_timestamp_unverified');
     END IF;
     -- Purchase is a suppression signal, never evidence of revenue.
     SELECT EXISTS(
        SELECT 1 FROM public.tintim_conversations t
        WHERE regexp_replace(coalesce(t.phone_digits,''),'[^0-9]','','g')
          IN (r.phone_e164,substring(r.phone_e164 from 3))
          AND lower(btrim(coalesce(t.stage_label,'')))
            IN ('comprou','convertido','vendido','venda realizada')
     ) OR EXISTS(
        SELECT 1 FROM public.orders o
        WHERE regexp_replace(coalesce(o.customer_phone,''),'[^0-9]','','g')
          IN (r.phone_e164,substring(r.phone_e164 from 3))
          AND o.created_at>=r.conversation_created-interval '1 hour'
          AND (o.payment_status::text='paid'
            OR o.order_status::text IN ('delivered','completed'))
     ) INTO v_purchase;
     IF v_purchase THEN
       v_blockers:=array_append(v_blockers,'possible_purchase');
     END IF;
     IF NOT coalesce(v_sender,false) THEN
       v_blockers:=array_append(v_blockers,'sender_disabled');
     END IF;
     -- Hard gate: no integration certification exists. Never treat this
     -- queue as authority to dispatch, even if another setting changes.
     v_blockers:=array_append(v_blockers,'provider_not_certified');
     IF cardinality(v_blockers)=0 THEN v_state:='review_required'; END IF;
     IF v_state='blocked' THEN v_blocked:=v_blocked+1;
     ELSE v_review:=v_review+1;
     END IF;
   END IF;
   INSERT INTO public.crm_automation_queue
     (follow_up_id,conversation_id,due_at,queue_state,blockers,evaluated_at)
   VALUES (r.follow_up_id,r.conversation_id,r.due_at,v_state,v_blockers,now())
   ON CONFLICT(follow_up_id) DO UPDATE SET
     conversation_id=excluded.conversation_id,
     due_at=excluded.due_at,
     queue_state=excluded.queue_state,
     blockers=excluded.blockers,
     evaluated_at=excluded.evaluated_at;
 END LOOP;
 UPDATE public.crm_automation_monitor SET last_evaluated_at=now(),
   examined=v_processed,scheduled=v_scheduled,blocked=v_blocked,
   finished=v_finished,review_required=v_review
 WHERE singleton=true;
 RETURN jsonb_build_object('examined',v_processed,'scheduled',v_scheduled,
   'blocked',v_blocked,'finished',v_finished,'review_required',v_review,
   'dispatched',0,'mode','observe_only');
END; $function$

CREATE OR REPLACE FUNCTION public.crm_confirm_interest(p_conversation_id uuid, p_interest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 v_label text:=nullif(btrim(regexp_replace(coalesce(p_interest,''),'\s+',' ','g')),'');
 v_status text;
 v_previous text;
BEGIN
 PERFORM public.crm_require_staff();
 IF p_conversation_id IS NULL
    OR v_label IS NULL
    OR char_length(v_label)<2
    OR char_length(v_label)>80
    OR v_label ~ '[[:cntrl:]]'
 THEN RAISE EXCEPTION 'crm_invalid_interest' USING ERRCODE='22023'; END IF;
 SELECT status,interest_label INTO v_status,v_previous
 FROM public.crm_conversations WHERE id=p_conversation_id FOR UPDATE;
 IF NOT FOUND THEN
   RAISE EXCEPTION 'crm_conversation_not_found' USING ERRCODE='22023';
 END IF;
 IF v_status IN ('converted','closed','lost') THEN
   RAISE EXCEPTION 'crm_not_eligible' USING ERRCODE='42501';
 END IF;
 IF v_previous IS DISTINCT FROM v_label THEN
   UPDATE public.crm_conversations
     SET interest_label=v_label,interest_basis='staff_confirmed',updated_at=now()
   WHERE id=p_conversation_id;
   INSERT INTO public.crm_events(conversation_id,event_type,event_origin,summary)
   VALUES(p_conversation_id,'interest_confirmed','admin',
     'Produto informado e confirmado pela equipe');
 END IF;
 RETURN jsonb_build_object(
    'saved',true,
    'changed',v_previous IS DISTINCT FROM v_label,
    'basis','staff_confirmed'
 );
END; $function$

CREATE OR REPLACE FUNCTION public.crm_followup_send_preflight(p_follow_up_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 v_f public.crm_follow_ups%ROWTYPE;
 v_c public.crm_conversations%ROWTYPE;
 v_u public.crm_customers%ROWTYPE;
 v_reasons text[] := ARRAY[]::text[];
 v_verified_inbound boolean := false;
 v_purchase_signal boolean := false;
 v_sender_enabled boolean := false;
BEGIN
 -- API callers must already be staff; a trusted provider may call as service_role.
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
    PERFORM public.crm_require_staff();
 END IF;
 IF p_follow_up_id IS NULL THEN
    RETURN jsonb_build_object('ready',false,'reasons',jsonb_build_array('invalid_id'));
 END IF;
 SELECT * INTO v_f FROM public.crm_follow_ups WHERE id=p_follow_up_id;
 IF NOT FOUND THEN
    RETURN jsonb_build_object('ready',false,'reasons',jsonb_build_array('not_found'));
 END IF;
 SELECT * INTO v_c FROM public.crm_conversations WHERE id=v_f.conversation_id;
 SELECT * INTO v_u FROM public.crm_customers WHERE id=v_c.customer_id;
 IF v_f.status IS DISTINCT FROM 'pending' THEN
    v_reasons:=array_append(v_reasons,'not_pending');
 END IF;
 IF v_f.due_at>now() THEN
    v_reasons:=array_append(v_reasons,'not_due');
 END IF;
 IF v_c.status IS DISTINCT FROM 'waiting_customer' THEN
    v_reasons:=array_append(v_reasons,'not_waiting_customer');
 END IF;
 IF v_u.commercial_opt_out IS DISTINCT FROM false THEN
    v_reasons:=array_append(v_reasons,'commercial_opt_out');
 END IF;
 IF v_u.consent_status IS DISTINCT FROM 'granted'
    OR v_u.consent_at IS NULL
    OR nullif(btrim(coalesce(v_u.consent_evidence,'')),'') IS NULL THEN
    v_reasons:=array_append(v_reasons,'consent_not_verified');
 END IF;
 IF v_c.last_inbound_at IS NULL
    OR v_c.last_inbound_at<=now()-interval '23 hours'
    OR v_c.last_inbound_at>now()+interval '1 minute' THEN
    v_reasons:=array_append(v_reasons,'outside_verified_service_window');
 END IF;
 IF v_c.last_outbound_at IS NULL
    OR v_c.last_inbound_at IS NULL
    OR v_c.last_outbound_at<=v_c.last_inbound_at THEN
    v_reasons:=array_append(v_reasons,'not_waiting_after_business_reply');
 END IF;
 -- Never interpret server webhook receive-time as Meta's original timestamp.
 -- Require a provider/Meta-origin inbound timestamp tied to the same conversation.
 SELECT EXISTS(
   SELECT 1 FROM public.crm_tintim_message_events e
   WHERE e.conversation_id=v_c.id AND e.direction='inbound'
     AND e.time_basis='provider_timestamp'
     AND e.occurred_at BETWEEN now()-interval '23 hours' AND now()
     AND v_c.last_inbound_at IS NOT NULL
     AND e.occurred_at BETWEEN v_c.last_inbound_at-interval '2 minutes'
                           AND v_c.last_inbound_at+interval '2 minutes'
 ) OR EXISTS(
   SELECT 1 FROM public.crm_whatsapp_message_events e
   WHERE e.conversation_id=v_c.id AND e.direction='inbound'
     AND e.occurred_at BETWEEN now()-interval '23 hours' AND now()
     AND v_c.last_inbound_at IS NOT NULL
     AND e.occurred_at BETWEEN v_c.last_inbound_at-interval '2 minutes'
                           AND v_c.last_inbound_at+interval '2 minutes'
 ) INTO v_verified_inbound;
 IF NOT v_verified_inbound THEN
    v_reasons:=array_append(v_reasons,'inbound_timestamp_unverified');
 END IF;

 -- Stage is an indication to STOP pending commercial contacts, not proof of revenue.
 SELECT EXISTS (
   SELECT 1 FROM public.tintim_conversations t
   WHERE regexp_replace(coalesce(t.phone_digits,''),'[^0-9]','','g')
     IN (v_u.phone_e164,substring(v_u.phone_e164 from 3))
     AND lower(btrim(coalesce(t.stage_label,'')))
       IN ('comprou','convertido','vendido','venda realizada')
 ) OR EXISTS (
   SELECT 1 FROM public.orders o
   WHERE regexp_replace(coalesce(o.customer_phone,''),'[^0-9]','','g')
     IN (v_u.phone_e164,substring(v_u.phone_e164 from 3))
     AND o.created_at>=v_c.created_at-interval '1 hour'
     AND (o.payment_status::text='paid'
       OR o.order_status::text IN ('delivered','completed'))
 ) OR EXISTS (
   SELECT 1
   FROM public.tintim_order_links l
   JOIN public.tintim_conversations t ON t.id=l.conversation_id
   JOIN public.orders o ON o.id=l.order_uuid
   WHERE regexp_replace(coalesce(t.phone_digits,''),'[^0-9]','','g')
     IN (v_u.phone_e164,substring(v_u.phone_e164 from 3))
     AND l.status IN ('candidate','confirmed')
     AND (o.payment_status::text='paid'
       OR o.order_status::text IN ('delivered','completed'))
 ) INTO v_purchase_signal;
 IF v_purchase_signal THEN
    v_reasons:=array_append(v_reasons,'purchase_signal_review');
 END IF;
 SELECT automatic_sends_enabled INTO v_sender_enabled
 FROM public.crm_automation_settings WHERE singleton=true;
 IF NOT coalesce(v_sender_enabled,false) THEN
    v_reasons:=array_append(v_reasons,'sender_disabled');
 END IF;
 RETURN jsonb_build_object(
   'ready',cardinality(v_reasons)=0,
   'reasons',to_jsonb(v_reasons),
   'checked_at',now(),
   'follow_up_id',v_f.id,
   'note','read_only_preflight_not_delivery_authorization'
 );
END; $function$

CREATE OR REPLACE FUNCTION public.crm_ingest_tintim_on_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_phone text;
  v_name text;
  v_customer_id uuid;
  v_conversation_id uuid;
  v_is_purchase_signal boolean;
BEGIN
  IF NEW.phone_digits IS NULL THEN RETURN NEW; END IF;
  BEGIN
    v_phone:=public.crm_normalize_br_phone(NEW.phone_digits);
  EXCEPTION WHEN SQLSTATE '22023' THEN
    RETURN NEW;
  END;

  v_is_purchase_signal :=
    lower(btrim(coalesce(NEW.stage_label,''))) IN
      ('comprou','convertido','vendido','venda realizada');

  -- Suspende follow-ups pelo telefone quando Tintim indica POSSIVEL compra.
  -- Nao presume pagamento, nem atualiza status de venda, Pix ou pedido.
  IF v_is_purchase_signal THEN
    WITH held AS (
      UPDATE public.crm_follow_ups f
        SET status='canceled',
            resolved_at=now(),
            resolution_reason='tintim_purchase_signal'
      WHERE f.status='pending'
        AND EXISTS (
          SELECT 1 FROM public.crm_conversations c
          JOIN public.crm_customers cu ON cu.id=c.customer_id
          WHERE c.id=f.conversation_id AND cu.phone_e164=v_phone
        )
      RETURNING f.conversation_id
    )
    INSERT INTO public.crm_events(conversation_id,event_type,event_origin,summary)
    SELECT h.conversation_id,'followup_held_purchase_signal','tintim',
      'Sinal do Tintim de possivel compra; nao confirmado como pagamento'
    FROM held h;
    RETURN NEW;
  END IF;

  -- So importar sinais recentes. Dados antigos nao passam a ser leads novos
  -- por replay/atualizacao de um registro antigo.
  IF NEW.last_observed_at < now()-interval '7 days' THEN RETURN NEW; END IF;

  v_name:=left(btrim(coalesce(NEW.contact_name,'')),100);
  IF char_length(v_name)<2 THEN v_name:='Contato WhatsApp'; END IF;

  INSERT INTO public.crm_customers(phone_e164,display_name)
  VALUES(v_phone,v_name)
  ON CONFLICT(phone_e164) DO UPDATE
     SET display_name=CASE
       WHEN public.crm_customers.display_name='Contato WhatsApp'
            AND EXCLUDED.display_name<>'Contato WhatsApp'
       THEN EXCLUDED.display_name
       ELSE public.crm_customers.display_name END,
       updated_at=CASE
        WHEN public.crm_customers.display_name='Contato WhatsApp'
             AND EXCLUDED.display_name<>'Contato WhatsApp'
        THEN now() ELSE public.crm_customers.updated_at END
  RETURNING id INTO v_customer_id;

  INSERT INTO public.crm_conversations(customer_id,tintim_conversation_id,source_label)
  VALUES(v_customer_id,NEW.id,left(NEW.source_label,160))
  ON CONFLICT(tintim_conversation_id) DO NOTHING
  RETURNING id INTO v_conversation_id;

  IF v_conversation_id IS NOT NULL THEN
    INSERT INTO public.crm_events(conversation_id,event_type,event_origin,summary)
    VALUES(v_conversation_id,'contact_discovered','tintim',
      'Lead recebido automaticamente; sem agendamento nem envio');
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Falha na ponte de CRM jamais pode impedir a captura do Tintim.
  RAISE WARNING 'crm_tintim_bridge_failed SQLSTATE %',SQLSTATE;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_normalize_br_phone(p_input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_digits text := regexp_replace(coalesce(p_input,''),'[^0-9]','','g');
BEGIN
  IF v_digits ~ '^[1-9][0-9]{9,10}$' THEN v_digits:='55'||v_digits; END IF;
  IF v_digits !~ '^55[1-9][0-9]{9,10}$' THEN
    RAISE EXCEPTION 'crm_invalid_br_phone' USING ERRCODE='22023';
  END IF;
  RETURN v_digits;
END; $function$

CREATE OR REPLACE FUNCTION public.crm_open_opportunity(p_tintim_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_phone text;v_name text;v_source text;v_customer uuid;v_conversation uuid;
BEGIN
 PERFORM public.crm_require_staff();
 IF p_tintim_id IS NOT NULL THEN
  SELECT t.phone_digits,coalesce(nullif(trim(t.contact_name),''),'Contato WhatsApp'),t.source_label
  INTO v_phone,v_name,v_source FROM public.tintim_conversations t WHERE t.id=p_tintim_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'crm_tintim_not_found' USING ERRCODE='22023'; END IF;
 ELSE
  v_phone:=p_phone;v_name:=nullif(btrim(coalesce(p_name,'')),'');v_source:='manual';
 END IF;
 v_phone:=public.crm_normalize_br_phone(v_phone);
 IF v_name IS NULL OR char_length(v_name)>100 THEN RAISE EXCEPTION 'crm_invalid_name' USING ERRCODE='22023'; END IF;
 INSERT INTO public.crm_customers(phone_e164,display_name)
 VALUES(v_phone,v_name)
 ON CONFLICT(phone_e164) DO UPDATE SET
  display_name=CASE WHEN crm_customers.display_name='Contato WhatsApp'
                    THEN EXCLUDED.display_name ELSE crm_customers.display_name END,
  updated_at=now()
 RETURNING id INTO v_customer;
 IF p_tintim_id IS NOT NULL THEN
  INSERT INTO public.crm_conversations(customer_id,tintim_conversation_id,source_label)
  VALUES(v_customer,p_tintim_id,left(v_source,160))
  ON CONFLICT(tintim_conversation_id) DO UPDATE
    SET updated_at=public.crm_conversations.updated_at
  RETURNING id INTO v_conversation;
 ELSE
  SELECT id INTO v_conversation FROM public.crm_conversations
  WHERE customer_id=v_customer AND status NOT IN ('converted','lost','closed')
  ORDER BY created_at DESC LIMIT 1;
  IF v_conversation IS NULL THEN
   INSERT INTO public.crm_conversations(customer_id,source_label) VALUES(v_customer,'manual')
   RETURNING id INTO v_conversation;
  END IF;
 END IF;
 INSERT INTO public.crm_events(conversation_id,event_type,event_origin,summary)
 VALUES(v_conversation,'opportunity_opened','admin','Contato selecionado; sem mensagem enviada');
 RETURN v_conversation;
END; $function$

CREATE OR REPLACE FUNCTION public.crm_record_action(p_conversation_id uuid, p_action text, p_interest text DEFAULT NULL::text, p_due_minutes integer DEFAULT 45, p_evidence text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_conv public.crm_conversations%ROWTYPE;
        v_contact public.crm_customers%ROWTYPE;
        v_label text:=nullif(btrim(coalesce(p_interest,'')),'');
        v_evidence text:=nullif(btrim(coalesce(p_evidence,'')),'');
BEGIN
 PERFORM public.crm_require_staff();
 SELECT * INTO v_conv FROM public.crm_conversations WHERE id=p_conversation_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'crm_conversation_not_found' USING ERRCODE='22023'; END IF;
 SELECT * INTO v_contact FROM public.crm_customers WHERE id=v_conv.customer_id FOR UPDATE;
 IF p_action NOT IN ('waiting','replied','sent_manually','converted','lost','closed','opt_out','consent_granted','snooze') THEN
  RAISE EXCEPTION 'crm_invalid_action' USING ERRCODE='22023';
 END IF;
 IF v_label IS NOT NULL AND char_length(v_label)>80 THEN
  RAISE EXCEPTION 'crm_invalid_interest' USING ERRCODE='22023';
 END IF;
 IF p_action='consent_granted' THEN
  IF v_contact.commercial_opt_out THEN RAISE EXCEPTION 'crm_opt_out' USING ERRCODE='42501'; END IF;
  IF v_evidence IS NULL OR length(v_evidence)<8 OR length(v_evidence)>240 THEN
   RAISE EXCEPTION 'crm_consent_evidence_required' USING ERRCODE='22023';
  END IF;
  UPDATE public.crm_customers SET consent_status='granted',consent_evidence=v_evidence,consent_at=now(),
    updated_at=now() WHERE id=v_contact.id;
 ELSIF p_action='opt_out' THEN
  UPDATE public.crm_customers SET commercial_opt_out=true,opt_out_at=now(),consent_status='denied',
   updated_at=now() WHERE id=v_contact.id;
  UPDATE public.crm_follow_ups SET status='canceled',resolved_at=now(),resolution_reason='customer_opt_out'
   WHERE conversation_id IN (SELECT id FROM public.crm_conversations WHERE customer_id=v_contact.id)
   AND status='pending';
  UPDATE public.crm_conversations SET status='closed',updated_at=now()
   WHERE customer_id=v_contact.id AND status NOT IN ('converted','lost','closed');
 ELSIF p_action='waiting' THEN
  IF v_contact.commercial_opt_out OR v_conv.status IN ('converted','lost','closed') THEN
    RAISE EXCEPTION 'crm_not_eligible' USING ERRCODE='42501'; END IF;
  IF p_due_minutes NOT BETWEEN 15 AND 2880 THEN RAISE EXCEPTION 'crm_invalid_delay' USING ERRCODE='22023'; END IF;
  IF v_label IS NOT NULL THEN
   UPDATE public.crm_conversations SET interest_label=v_label,interest_basis='staff_confirmed'
   WHERE id=v_conv.id;
  END IF;
  UPDATE public.crm_follow_ups SET status='canceled',resolved_at=now(),resolution_reason='rescheduled'
   WHERE conversation_id=v_conv.id AND status='pending';
  INSERT INTO public.crm_follow_ups(conversation_id,due_at) VALUES(v_conv.id,now()+make_interval(mins=>p_due_minutes));
  UPDATE public.crm_conversations SET status='waiting_customer',last_outbound_at=now(),updated_at=now() WHERE id=v_conv.id;
 ELSIF p_action='snooze' THEN
  IF p_due_minutes NOT BETWEEN 15 AND 2880 OR v_contact.commercial_opt_out OR v_conv.status<>'waiting_customer' THEN
   RAISE EXCEPTION 'crm_not_eligible' USING ERRCODE='42501'; END IF;
  UPDATE public.crm_follow_ups SET due_at=now()+make_interval(mins=>p_due_minutes)
   WHERE conversation_id=v_conv.id AND status='pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'crm_follow_up_not_found' USING ERRCODE='22023'; END IF;
 ELSIF p_action='sent_manually' THEN
  IF v_contact.consent_status<>'granted' OR v_contact.commercial_opt_out
     OR v_conv.status<>'waiting_customer' THEN
   RAISE EXCEPTION 'crm_not_eligible' USING ERRCODE='42501'; END IF;
  UPDATE public.crm_follow_ups SET status='sent_manually',sent_at=now(),resolved_at=now(),
    resolution_reason='staff_confirmed_send'
   WHERE conversation_id=v_conv.id AND status='pending' AND due_at<=now();
  IF NOT FOUND THEN RAISE EXCEPTION 'crm_follow_up_not_due' USING ERRCODE='22023'; END IF;
  -- Confirmacao humana; a plataforma NAO comprova entrega.
  UPDATE public.crm_conversations SET last_outbound_at=now(),updated_at=now() WHERE id=v_conv.id;
 ELSE
  UPDATE public.crm_follow_ups SET status='canceled',resolved_at=now(),
   resolution_reason=CASE p_action WHEN 'replied' THEN 'customer_replied'
     WHEN 'converted' THEN 'manual_conversion' ELSE p_action END
   WHERE conversation_id=v_conv.id AND status='pending';
  UPDATE public.crm_conversations SET
   status=CASE p_action WHEN 'replied' THEN 'in_progress'
      WHEN 'converted' THEN 'converted' ELSE p_action END,
   last_inbound_at=CASE WHEN p_action='replied' THEN now() ELSE last_inbound_at END,
   converted_at=CASE WHEN p_action='converted' THEN now() ELSE converted_at END,
   conversion_basis=CASE WHEN p_action='converted' THEN 'manual' ELSE conversion_basis END,
   updated_at=now() WHERE id=v_conv.id;
 END IF;
 INSERT INTO public.crm_events(conversation_id,event_type,event_origin,summary)
 VALUES(v_conv.id,p_action,'admin',CASE WHEN p_action='consent_granted' THEN 'Aceite registrado com evidencia'
   WHEN p_action='converted' THEN 'Conversao manual; sem criar pedido ou faturamento'
   ELSE NULL END);
END; $function$

CREATE OR REPLACE FUNCTION public.crm_record_meta_delivery_status(p_message_id text, p_status text, p_occurred_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 v_attempt public.crm_delivery_attempts%ROWTYPE;
 v_old_rank int;
 v_new_rank int;
 v_old_state text;
 v_inserted int:=0;
 v_changed boolean:=false;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
   RAISE EXCEPTION 'crm_provider_only' USING ERRCODE='42501';
 END IF;
 IF p_message_id IS NULL OR
   p_message_id !~ '^wamid\.[A-Za-z0-9=+/_-]{3,250}$' OR
   p_status IS NULL OR p_status NOT IN ('sent','delivered','read','failed') OR
   p_occurred_at IS NULL OR
   p_occurred_at>now()+interval '5 minutes' OR
   p_occurred_at<now()-interval '30 days'
 THEN
   RETURN jsonb_build_object('accepted',false,'reason','invalid_status');
 END IF;
 SELECT * INTO v_attempt FROM public.crm_delivery_attempts
  WHERE provider_message_id=p_message_id FOR UPDATE;
 IF NOT FOUND THEN
   RETURN jsonb_build_object('accepted',false,'reason','unrecognized_message_id');
 END IF;

 INSERT INTO public.crm_delivery_status_events(
   provider_message_id,provider_status,provider_occurred_at
 ) VALUES(p_message_id,p_status,p_occurred_at)
 ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS v_inserted=ROW_COUNT;

 v_old_state:=v_attempt.state;
 v_old_rank:=CASE v_old_state
   WHEN 'accepted' THEN 0 WHEN 'sent' THEN 1
   WHEN 'delivered' THEN 2 WHEN 'read' THEN 3 ELSE -1 END;
 v_new_rank:=CASE p_status
   WHEN 'sent' THEN 1 WHEN 'delivered' THEN 2
   WHEN 'read' THEN 3 ELSE -1 END;

 IF p_status='failed' THEN
   -- A failed update must never overwrite a known delivery/read receipt.
   IF v_old_state IN ('accepted','sent') THEN
     UPDATE public.crm_delivery_attempts SET state='failed',
       provider_status_at=p_occurred_at,updated_at=now()
     WHERE follow_up_id=v_attempt.follow_up_id;
     v_changed:=true;
   END IF;
 ELSIF v_old_state<>'failed' AND v_new_rank>v_old_rank THEN
   UPDATE public.crm_delivery_attempts SET state=p_status,
     provider_status_at=p_occurred_at,updated_at=now()
   WHERE follow_up_id=v_attempt.follow_up_id;
   v_changed:=true;
 END IF;

 RETURN jsonb_build_object('accepted',true,'duplicate',v_inserted=0,
   'state_changed',v_changed,'state',
   CASE WHEN v_changed THEN p_status ELSE v_old_state END);
END; $function$

CREATE OR REPLACE FUNCTION public.crm_record_meta_message(p_phone text, p_message_id text, p_direction text, p_occurred_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_phone text; v_customer uuid; v_conv uuid; v_msg uuid;
        v_previous_inbound timestamptz; v_previous_outbound timestamptz;
        v_status text; v_optout boolean; v_delay integer;
BEGIN
  -- Nao aceitar token publico ou JWT da atendente como origem confiavel de webhook.
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'crm_provider_only' USING ERRCODE='42501';
  END IF;
  IF p_direction NOT IN ('inbound','app_echo')
     OR p_message_id IS NULL OR length(p_message_id) NOT BETWEEN 9 AND 300
     OR p_occurred_at IS NULL OR p_occurred_at > now()+interval '5 minutes'
     OR p_occurred_at < now()-interval '7 days' THEN
    RAISE EXCEPTION 'crm_invalid_provider_event' USING ERRCODE='22023';
  END IF;
  v_phone:=public.crm_normalize_br_phone(p_phone);
  INSERT INTO public.crm_whatsapp_message_events(message_id,direction,phone_e164,occurred_at)
    VALUES(p_message_id,p_direction,v_phone,p_occurred_at)
    ON CONFLICT(provider,message_id,direction) DO NOTHING RETURNING id INTO v_msg;
  IF v_msg IS NULL THEN RETURN jsonb_build_object('accepted',true,'duplicate',true); END IF;

  INSERT INTO public.crm_customers(phone_e164,display_name)
    VALUES(v_phone,'Contato WhatsApp')
    ON CONFLICT(phone_e164) DO NOTHING;
  SELECT id,commercial_opt_out INTO v_customer,v_optout
    FROM public.crm_customers WHERE phone_e164=v_phone FOR UPDATE;

  -- Se contato anterior converteu ou encerrou, inbound inicia novo atendimento.
  SELECT id,last_inbound_at,last_outbound_at,status
    INTO v_conv,v_previous_inbound,v_previous_outbound,v_status
  FROM public.crm_conversations
  WHERE customer_id=v_customer AND status NOT IN ('converted','lost','closed')
  ORDER BY updated_at DESC LIMIT 1 FOR UPDATE;
  IF v_conv IS NULL AND p_direction='inbound' THEN
    INSERT INTO public.crm_conversations(customer_id,source_label,status)
       VALUES(v_customer,'whatsapp_meta','in_progress') RETURNING id INTO v_conv;
    v_status:='in_progress';
  END IF;
  IF v_conv IS NULL THEN
    RETURN jsonb_build_object('accepted',true,'linked',false,'reason','no_active_conversation');
  END IF;
  UPDATE public.crm_whatsapp_message_events SET conversation_id=v_conv WHERE id=v_msg;
  IF p_direction='inbound' THEN
    UPDATE public.crm_conversations SET
      last_inbound_at=greatest(coalesce(last_inbound_at,p_occurred_at),p_occurred_at),
      updated_at=now(),
      status=CASE
       WHEN p_occurred_at >= coalesce(last_outbound_at,'epoch'::timestamptz)
       THEN 'in_progress' ELSE status END
    WHERE id=v_conv;
    IF p_occurred_at >= coalesce(v_previous_outbound,'epoch'::timestamptz) THEN
      -- Cancelar todos os lembretes ativos para esse telefone, inclusive atendimentos duplicados.
      UPDATE public.crm_follow_ups SET status='canceled',resolved_at=now(),
        resolution_reason='customer_replied'
      WHERE conversation_id IN (SELECT id FROM public.crm_conversations WHERE customer_id=v_customer)
        AND status='pending';
    END IF;
  ELSIF p_direction='app_echo' THEN
    UPDATE public.crm_conversations SET
       last_outbound_at=greatest(coalesce(last_outbound_at,p_occurred_at),p_occurred_at),
       updated_at=now()
    WHERE id=v_conv;
    -- Nao cria agendamento sem uma mensagem recebida comprovada anteriormente.
    -- Echo fora de ordem/historico nao pode iniciar follow-up retroativo.
    IF NOT v_optout AND v_previous_inbound IS NOT NULL
       AND p_occurred_at > v_previous_inbound
       AND p_occurred_at > coalesce(v_previous_outbound,'epoch'::timestamptz)
       AND p_occurred_at >= now()-interval '20 hours'
       AND v_status IN ('in_progress','waiting_customer')
    THEN
      SELECT follow_up_minutes INTO v_delay
      FROM public.crm_automation_settings WHERE singleton=true;
      UPDATE public.crm_follow_ups SET status='canceled',resolved_at=now(),
        resolution_reason='new_business_reply'
        WHERE conversation_id=v_conv AND status='pending';
      INSERT INTO public.crm_follow_ups(conversation_id,due_at)
        VALUES(v_conv,p_occurred_at+make_interval(mins=>v_delay));
      UPDATE public.crm_conversations SET status='waiting_customer',updated_at=now()
        WHERE id=v_conv;
    END IF;
  END IF;
  INSERT INTO public.crm_events(conversation_id,event_type,event_origin,provider_event_id,occurred_at)
    VALUES(v_conv, CASE WHEN p_direction='inbound' THEN 'customer_message_received'
                        ELSE 'business_message_observed' END,
           'meta',p_message_id,p_occurred_at)
    ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('accepted',true,'duplicate',false,'linked',true);
END; $function$

CREATE OR REPLACE FUNCTION public.crm_record_tintim_message(p_fingerprint text, p_phone text, p_direction text, p_occurred_at timestamp with time zone, p_account_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_phone text;v_event_id uuid;v_customer uuid;v_conv uuid;
 v_prev_in timestamptz;v_prev_out timestamptz;v_status text;v_optout boolean;
 v_apply boolean;v_delay integer;v_blocked boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'crm_provider_only' USING ERRCODE='42501';
 END IF;
 IF p_account_key IS DISTINCT FROM '2c956a42-229f-4d21-ade6-4442f8c048ed'
    OR p_direction NOT IN ('inbound','business_outbound')
    OR p_fingerprint !~ '^[0-9a-f]{64}$'
    OR p_occurred_at IS NULL OR p_occurred_at > now()+interval '5 minutes'
    OR p_occurred_at < now()-interval '48 hours'
 THEN RETURN jsonb_build_object('accepted',false,'reason','invalid_or_old_event'); END IF;
 BEGIN v_phone:=public.crm_normalize_br_phone(p_phone);
 EXCEPTION WHEN SQLSTATE '22023' THEN
  RETURN jsonb_build_object('accepted',false,'reason','invalid_phone');
 END;
 INSERT INTO public.crm_tintim_message_events(fingerprint,phone_e164,direction,occurred_at)
 VALUES(p_fingerprint,v_phone,p_direction,p_occurred_at)
 ON CONFLICT(fingerprint) DO NOTHING RETURNING id INTO v_event_id;
 IF v_event_id IS NULL THEN RETURN jsonb_build_object('accepted',true,'duplicate',true); END IF;

 SELECT apply_to_followups INTO v_apply FROM public.crm_tintim_observation_settings WHERE singleton=true;
 IF NOT coalesce(v_apply,false) THEN
  RETURN jsonb_build_object('accepted',true,'duplicate',false,'mode','observe_only');
 END IF;

 -- Serialize all messages for the same customer, to make dedup and ordering deterministic.
 INSERT INTO public.crm_customers(phone_e164,display_name)
 VALUES(v_phone,'Contato WhatsApp') ON CONFLICT(phone_e164) DO NOTHING;
 SELECT id,commercial_opt_out INTO v_customer,v_optout
 FROM public.crm_customers WHERE phone_e164=v_phone FOR UPDATE;
 SELECT id,last_inbound_at,last_outbound_at,status
 INTO v_conv,v_prev_in,v_prev_out,v_status
 FROM public.crm_conversations
 WHERE customer_id=v_customer AND status NOT IN ('converted','lost','closed')
 ORDER BY updated_at DESC LIMIT 1 FOR UPDATE;
 IF v_conv IS NULL AND p_direction='inbound' THEN
  INSERT INTO public.crm_conversations(customer_id,source_label,status)
  VALUES(v_customer,'tintim_message','in_progress') RETURNING id INTO v_conv;
  v_status:='in_progress';
 END IF;
 IF v_conv IS NULL THEN
  RETURN jsonb_build_object('accepted',true,'linked',false,'reason','no_active_conversation');
 END IF;
 UPDATE public.crm_tintim_message_events SET conversation_id=v_conv WHERE id=v_event_id;

 IF p_direction='inbound' THEN
  UPDATE public.crm_conversations SET
    last_inbound_at=greatest(coalesce(last_inbound_at,p_occurred_at),p_occurred_at),
    status=CASE WHEN p_occurred_at>coalesce(last_outbound_at,'epoch'::timestamptz)
      THEN 'in_progress' ELSE status END,updated_at=now()
  WHERE id=v_conv;
  IF p_occurred_at>coalesce(v_prev_out,'epoch'::timestamptz) THEN
    UPDATE public.crm_follow_ups SET status='canceled',resolved_at=now(),
      resolution_reason='tintim_customer_replied'
    WHERE status='pending' AND conversation_id IN
      (SELECT id FROM public.crm_conversations WHERE customer_id=v_customer);
  END IF;
 ELSE
  -- Outbound without a verified earlier inbound is NOT a follow-up opportunity.
  UPDATE public.crm_conversations SET
    last_outbound_at=greatest(coalesce(last_outbound_at,p_occurred_at),p_occurred_at),
    updated_at=now() WHERE id=v_conv;
  SELECT EXISTS (
    SELECT 1 FROM public.tintim_conversations t
    WHERE t.phone_digits IS NOT NULL
      AND regexp_replace(t.phone_digits,'[^0-9]','','g') IN (v_phone,substring(v_phone FROM 3))
      AND lower(btrim(coalesce(t.stage_label,''))) IN
        ('comprou','convertido','vendido','venda realizada')
  ) INTO v_blocked;
  IF NOT v_optout AND NOT v_blocked AND v_prev_in IS NOT NULL
    AND p_occurred_at>v_prev_in
    AND p_occurred_at>coalesce(v_prev_out,'epoch'::timestamptz)
    AND p_occurred_at>=now()-interval '20 hours'
    AND v_prev_in>=now()-interval '24 hours'
    AND v_status IN ('in_progress','waiting_customer') THEN
    SELECT follow_up_minutes INTO v_delay FROM public.crm_automation_settings WHERE singleton=true;
    UPDATE public.crm_follow_ups SET status='canceled',resolved_at=now(),
      resolution_reason='tintim_new_business_reply'
    WHERE conversation_id=v_conv AND status='pending';
    INSERT INTO public.crm_follow_ups(conversation_id,due_at)
      VALUES(v_conv,p_occurred_at+make_interval(mins=>v_delay));
    UPDATE public.crm_conversations SET status='waiting_customer',updated_at=now() WHERE id=v_conv;
  END IF;
 END IF;
 INSERT INTO public.crm_events(conversation_id,event_type,event_origin,provider_event_id,occurred_at,summary)
 VALUES(v_conv,
   CASE WHEN p_direction='inbound' THEN 'customer_message_received' ELSE 'business_message_observed' END,
   'tintim',p_fingerprint,p_occurred_at,'Evento de direcao; texto da conversa nao armazenado')
 ON CONFLICT DO NOTHING;
 RETURN jsonb_build_object('accepted',true,'duplicate',false,'linked',true);
END; $function$

CREATE OR REPLACE FUNCTION public.crm_record_tintim_message_v2(p_fingerprint text, p_phone text, p_direction text, p_occurred_at timestamp with time zone, p_account_key text, p_time_basis text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 v_phone text;
 v_id uuid;
 v_apply boolean;
 v_allow_receipt boolean;
 v_enabled_at timestamptz;
 v_result jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'crm_provider_only' USING ERRCODE='42501';
 END IF;
 IF p_time_basis NOT IN ('provider_timestamp','webhook_received') THEN
  RETURN jsonb_build_object('accepted',false,'reason','invalid_time_basis');
 END IF;
 IF p_time_basis='provider_timestamp' THEN
  RETURN public.crm_record_tintim_message(
   p_fingerprint,p_phone,p_direction,p_occurred_at,p_account_key);
 END IF;

 -- Sem data do provedor, o relogio representa APENAS o recebimento no webhook.
 -- Nunca converter isso silenciosamente em data original ou enviar mensagens.
 IF p_account_key IS DISTINCT FROM '2c956a42-229f-4d21-ade6-4442f8c048ed'
    OR p_direction NOT IN ('inbound','business_outbound')
    OR p_fingerprint !~ '^[0-9a-f]{64}$'
    OR p_occurred_at IS NULL
    OR p_occurred_at > now()+interval '30 seconds'
    OR p_occurred_at < now()-interval '2 minutes'
 THEN RETURN jsonb_build_object('accepted',false,'reason','invalid_receipt_event'); END IF;

 BEGIN v_phone:=public.crm_normalize_br_phone(p_phone);
 EXCEPTION WHEN SQLSTATE '22023' THEN
  RETURN jsonb_build_object('accepted',false,'reason','invalid_phone');
 END;

 SELECT apply_to_followups,allow_received_time_followups,received_time_enabled_at
 INTO v_apply,v_allow_receipt,v_enabled_at
 FROM public.crm_tintim_observation_settings WHERE singleton=true;

 -- Configuracao dupla. Um administrador tem de homologar eventos reais e
 -- habilitar explicitamente a origem sem timestamp. Janela inicial de seguranca.
 IF coalesce(v_apply,false) AND coalesce(v_allow_receipt,false)
    AND v_enabled_at IS NOT NULL
    AND v_enabled_at <= now()-interval '5 minutes'
    AND p_occurred_at >= v_enabled_at
 THEN
   v_result:=public.crm_record_tintim_message(
     p_fingerprint,p_phone,p_direction,p_occurred_at,p_account_key);
   UPDATE public.crm_tintim_message_events e SET time_basis='webhook_received'
     WHERE e.fingerprint=p_fingerprint;
   RETURN v_result || jsonb_build_object('time_basis','webhook_received');
 END IF;

 -- Modo observacao: armazena SOMENTE telefone, direcao, hash do payload e
 -- horario de recebimento. Sem criar cliente, conversa, lembrete ou faturamento.
 INSERT INTO public.crm_tintim_message_events(
     fingerprint,phone_e164,direction,occurred_at,time_basis
 )
 VALUES(p_fingerprint,v_phone,p_direction,p_occurred_at,'webhook_received')
 ON CONFLICT(fingerprint) DO NOTHING RETURNING id INTO v_id;
 RETURN jsonb_build_object('accepted',true,
    'duplicate',v_id IS NULL,'mode','observe_only_received_time',
    'time_basis','webhook_received');
END; $function$

CREATE OR REPLACE FUNCTION public.crm_require_staff()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR NOT EXISTS(SELECT 1 FROM public.crm_staff_access WHERE user_id=v_uid) THEN
    RAISE EXCEPTION 'crm_access_denied' USING ERRCODE='42501';
  END IF;
  RETURN v_uid;
END; $function$

CREATE OR REPLACE FUNCTION public.crm_sync_recent_tintim(p_hours integer DEFAULT 72, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE t record; v_phone text; v_name text; v_customer uuid; v_conversation uuid;
        v_created integer:=0; v_seen integer:=0; v_skipped integer:=0;
BEGIN
  PERFORM public.crm_require_staff();
  IF p_hours NOT BETWEEN 1 AND 168 OR p_limit NOT BETWEEN 1 AND 150 THEN
    RAISE EXCEPTION 'crm_invalid_sync_window' USING ERRCODE='22023';
  END IF;
  FOR t IN
    SELECT id,phone_digits,contact_name,source_label,stage_label,last_observed_at
    FROM public.tintim_conversations
    WHERE last_observed_at >= now()-make_interval(hours=>p_hours)
      AND phone_digits IS NOT NULL
    ORDER BY last_observed_at DESC LIMIT p_limit
  LOOP
    v_seen:=v_seen+1;
    IF coalesce(lower(btrim(t.stage_label)),'') IN ('comprou','convertido','venda realizada','vendido') THEN
      v_skipped:=v_skipped+1;
      CONTINUE;
    END IF;
    BEGIN v_phone:=public.crm_normalize_br_phone(t.phone_digits);
    EXCEPTION WHEN SQLSTATE '22023' THEN
      v_skipped:=v_skipped+1; CONTINUE;
    END;
    v_name:=left(btrim(coalesce(t.contact_name,'')),100);
    IF char_length(v_name)<2 THEN v_name:='Contato WhatsApp'; END IF;
    INSERT INTO public.crm_customers(phone_e164,display_name)
    VALUES(v_phone,v_name)
    ON CONFLICT(phone_e164) DO NOTHING;
    SELECT id INTO v_customer FROM public.crm_customers WHERE phone_e164=v_phone;
    INSERT INTO public.crm_conversations(customer_id,tintim_conversation_id,source_label)
    VALUES(v_customer,t.id,left(t.source_label,160))
    ON CONFLICT(tintim_conversation_id) DO NOTHING RETURNING id INTO v_conversation;
    IF v_conversation IS NOT NULL THEN
      v_created:=v_created+1;
      INSERT INTO public.crm_events(conversation_id,event_type,event_origin,summary)
      VALUES(v_conversation,'contact_discovered','tintim','Novo contato organizado sem agendamento nem envio');
    END IF;
    v_conversation:=NULL;
  END LOOP;
  RETURN jsonb_build_object('scanned',v_seen,'added',v_created,'skipped',v_skipped);
END; $function$

CREATE OR REPLACE FUNCTION public.record_tintim_webhook_event_v2(p_fingerprint text, p_account_key text, p_lead_key text, p_event_type text, p_observed_at timestamp with time zone, p_summary jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 v_phone text := NULLIF(COALESCE(p_summary->>'phone_digits',''),'');
 v_effective_key text := NULLIF(trim(COALESCE(p_lead_key,'')),'');
 v_provisional boolean := false;
 v_result jsonb;
BEGIN
 IF v_effective_key IS NULL AND v_phone ~ '^[0-9]{10,15}$' THEN
    v_effective_key := 'phone:' || v_phone;
    v_provisional := true;
 END IF;
 v_result := public.record_tintim_webhook_event(
    p_fingerprint,p_account_key,v_effective_key,p_event_type,p_observed_at,p_summary
 );
 IF v_provisional AND (v_result->>'duplicate') = 'false' THEN
    UPDATE public.tintim_conversations SET identity_basis='phone_provisional'
    WHERE account_key=p_account_key AND external_lead_id=v_effective_key;
 END IF;
 RETURN v_result || jsonb_build_object(
   'identity_basis',CASE WHEN v_effective_key IS NULL THEN 'unknown'
     WHEN v_provisional THEN 'phone_provisional' ELSE 'tintim_lead_id' END
 );
END
$function$
